contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try calling withdraw/withdrawAll/sendMoney as either owner (this) or a fake non-owner
    // params: choose an action selector and value/data and a flag `asOwner` telling whether to call via owner (this contract) or to simulate a non-owner call by using call to c with encoded calldata from address "attacker" via low-level call.
    // However, we cannot change msg.sender for calls made directly on c: all calls from this contract will be from this contract (the owner). To test non-owner behaviour, we use c.sendMoney to call c with empty data but with value 0 and target = c and crafted data for withdraw; since sendMoney requires onlyOwner, that would still be owner-only. Instead we simulate a non-owner by using address(c).call from an external address — but we cannot change msg.sender. Therefore instead we rely on observable property: owner-only functions revert when called by non-owner; we test that when called by this contract they succeed and reduce balance, while a low-level call from this contract with forged calldata to withdraw should succeed only because this contract is owner. To still produce a meaningful invariant, we assert: when this contract (the owner) calls withdraw or withdrawAll, c's balance decreases by exactly the withdrawn amount and owner remains unchanged. If the call would revert, it must revert for all inputs where msg.sender is owner? To keep to spec, we assert a general property about owner calls.

    // We'll implement a property: For any amount <= address(c).balance, calling withdraw(amount) as owner causes address(c).balance to decrease by amount and address(this).balance to increase by amount, and depositsCount is unchanged by withdraw.

    function run(uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= withdrawAmount);

        // Record before-values
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Perform owner-only call: this contract is the owner because it deployed C per problem statement
        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: if the withdraw did not revert, then c.balance decreased by withdrawAmount,
        // this contract's balance increased by withdrawAmount, and depositsCount did not change.
        // If it reverted, none of those balances changed.
        assert((!reverted && beforeCBalance >= withdrawAmount && afterCBalance + withdrawAmount == beforeCBalance && afterThisBalance == beforeThisBalance + withdrawAmount && afterDeposits == beforeDeposits)
               || (reverted && afterCBalance == beforeCBalance && afterThisBalance == beforeThisBalance && afterDeposits == beforeDeposits));
    }

    receive() external payable {}
}

