// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= withdrawAmount);
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        assertTrue((!reverted && beforeCBalance >= withdrawAmount && afterCBalance + withdrawAmount == beforeCBalance && afterThisBalance == beforeThisBalance + withdrawAmount && afterDeposits == beforeDeposits)
               || (reverted && afterCBalance == beforeCBalance && afterThisBalance == beforeThisBalance && afterDeposits == beforeDeposits));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
